export default function pLimit(concurrency: number | Options): LimitFunction;

export type Options = {
	/**
	Concurrency limit.

	Minimum: `1`.
	*/
	readonly concurrency: number;

	/**
	Reject pending promises with an `AbortError` when `clearQueue()` is called.

	Default: `false`.

	This is recommended if you await the returned promises, for example with `Promise.all`, so pending tasks do not remain unresolved after `clearQueue()`.
	*/
	readonly rejectOnClear?: boolean;
};

/**
Returns a function with limited concurrency.

The returned function manages its own concurrent executions, allowing you to call it multiple times without exceeding the specified concurrency limit.

Ideal for scenarios where you need to control the number of simultaneous executions of a single function, rather than managing concurrency across multiple functions.

@param function_ - Promise-returning/async function.
@return Function with limited concurrency.

@example
```
import {limitFunction} from 'p-limit';

const limitedFunction = limitFunction(async () => {
	return doSomething();
}, {concurrency: 1});

const input = Array.from({length: 10}, limitedFunction);

// Only one promise is run at once.
await Promise.all(input);
```
*/
export function limitFunction<Arguments extends unknown[], ReturnType>(
	function_: (...arguments_: Arguments) => PromiseLike<ReturnType>,
	options: Options
): ((...arguments_: Arguments) => Promise<ReturnType>) & Pick<LimitFunction, 'clearQueue' | 'onIdle'>;

import test from 'node:test';
import assert from 'node:assert/strict';
import pLimit, {limitFunction} from './index.js';

const turn = () => new Promise(resolve => {
	setImmediate(resolve);
});

const verifyCompletionReaction = async wrapped => {
	const first = Promise.withResolvers();
	const second = Promise.withResolvers();
	let followUp;
	let reported = false;
	const limit = wrapped
		? limitFunction(which => which === 0 ? first.promise : second.promise, {concurrency: 1})
		: pLimit(1);
	const invoke = which => wrapped
		? limit(which)
		: limit(() => which === 0 ? first.promise : second.promise);
	try {
		const initial = invoke(0);
		// Register the actual consumer reaction before the idle waiter.
		const enqueued = initial.then(() => { // eslint-disable-line promise/prefer-await-to-then
			followUp = invoke(1);
		});
		const idle = limit.onIdle().then(() => { // eslint-disable-line promise/prefer-await-to-then
			reported = true;
		});
		await turn();
		assert.equal(reported, false);
		first.resolve();
		await enqueued;
		await turn();
		assert.equal(reported, false, 'onIdle reported while the completion reaction job was held');
		second.resolve();
		await followUp;
		await idle;
		assert.equal(reported, true);
	} finally {
		first.resolve();
		second.resolve();
	}
};

test('limiter completion reaction does not report idle early', {timeout: 4000}, async () => {
	await verifyCompletionReaction(false);
});

test('wrapper completion reaction does not report idle early', {timeout: 4000}, async () => {
	await verifyCompletionReaction(true);
});

import {setTimeout as delay} from 'node:timers/promises';
import test from 'ava';
import pLimit, {limitFunction} from './index.js';

test('onIdle resolves normally when already idle', async t => {
	const limit = pLimit(2);

	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);

	await t.notThrowsAsync(limit.onIdle());
});

test('onIdle waits for running and queued jobs', async t => {
	const limit = pLimit(1);
	const completed = [];

	const first = limit(async () => {
		await delay(50);
		completed.push('first');
	});
	const second = limit(async () => {
		await delay(10);
		completed.push('second');
	});

	let idle = false;
	const markIdle = async () => {
		await limit.onIdle();
		idle = true;
	};

	const idlePromise = markIdle();

	t.false(idle);
	await idlePromise;
	t.true(idle);
	t.deepEqual(completed, ['first', 'second']);
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);

	await Promise.all([first, second]);
});

test('onIdle supports multiple concurrent waiters', async t => {
	const limit = pLimit(1);

	limit(() => delay(30));

	const results = [];
	const waiters = Array.from({length: 5}, (_, index) => (async () => {
		await limit.onIdle();
		results.push(index);
	})());

	await Promise.all(waiters);
	t.deepEqual(results, [0, 1, 2, 3, 4]);
});

test('onIdle resolves after a rejected job settles', async t => {
	const limit = pLimit(1);
	const error = new Error('🦄');

	const rejected = limit(async () => {
		await delay(20);
		throw error;
	});

	const idlePromise = limit.onIdle();

	await t.throwsAsync(rejected, {is: error});
	await t.notThrowsAsync(idlePromise);
	t.is(limit.activeCount, 0);
});

test('onIdle does not resolve while a job enqueues another job on resolution', async t => {
	const limit = pLimit(1);
	const order = [];

	const outer = limit(async () => {
		await delay(20);
		order.push('outer');
		// Enqueue a new job before the outer job settles.
		limit(async () => {
			await delay(20);
			order.push('inner');
		});
	});

	let idle = false;
	const markIdle = async () => {
		await limit.onIdle();
		idle = true;
	};

	const idlePromise = markIdle();

	// Give the idle check a chance to (incorrectly) fire early.
	await delay(30);
	t.false(idle);
	t.is(limit.activeCount, 1);

	await idlePromise;
	t.true(idle);
	t.deepEqual(order, ['outer', 'inner']);
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);

	await outer;
});

test('onIdle counts reserved slots as active', async t => {
	const limit = pLimit(2);

	const runningPromise = limit(() => delay(40));
	const reservedPromise = limit(() => delay(40));

	t.is(limit.activeCount, 2);

	let idle = false;
	const markIdle = async () => {
		await limit.onIdle();
		idle = true;
	};

	const idlePromise = markIdle();

	await delay(10);
	t.false(idle);

	await idlePromise;
	t.true(idle);

	await Promise.all([runningPromise, reservedPromise]);
});

test('clearQueue releases onIdle waiters when queue is empty and no jobs are active (rejectOnClear: false)', async t => {
	const limit = pLimit(1);

	const runningPromise = limit(() => delay(20));
	const discarded = limit(() => delay(1000));
	const discardedToo = limit(() => delay(1000));

	await Promise.resolve();
	t.is(limit.pendingCount, 2);

	const idlePromise = limit.onIdle();

	limit.clearQueue();
	t.is(limit.pendingCount, 0);

	await t.notThrowsAsync(idlePromise);
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);

	await runningPromise;

	// The discarded promises intentionally stay unresolved under rejectOnClear: false.
	// They are still pending promises, not settled ones.
	t.true(discarded instanceof Promise);
	t.true(discardedToo instanceof Promise);
});

test('clearQueue releases onIdle waiters when there are no active jobs (rejectOnClear: false)', async t => {
	const limit = pLimit(2);

	// Fill the reserved/running slots.
	const runningOne = limit(() => delay(30));
	const runningTwo = limit(() => delay(30));
	limit(() => delay(1000));

	await Promise.resolve();
	t.is(limit.pendingCount, 1);

	limit.clearQueue();
	t.is(limit.pendingCount, 0);

	await t.notThrowsAsync(limit.onIdle());
	t.is(limit.activeCount, 0);

	await Promise.all([runningOne, runningTwo]);
});

test('limitFunction exposes onIdle', async t => {
	const limitedFunction = limitFunction(async () => {
		await delay(20);
		return 'ok';
	}, {concurrency: 1});

	const first = limitedFunction();
	const second = limitedFunction();

	let idle = false;
	const markIdle = async () => {
		await limitedFunction.onIdle();
		idle = true;
	};

	const idlePromise = markIdle();

	t.false(idle);
	await idlePromise;
	t.true(idle);

	t.deepEqual(await Promise.all([first, second]), ['ok', 'ok']);
});

test('limitFunction onIdle resolves immediately when idle', async t => {
	const limitedFunction = limitFunction(async () => 'ok', {concurrency: 1});

	await t.notThrowsAsync(limitedFunction.onIdle());
});

test('onIdle preserves FIFO ordering and concurrency changes', async t => {
	const limit = pLimit(1);
	const order = [];

	const promises = Array.from({length: 6}, (_, index) => limit(async () => {
		order.push(index);
		await delay(5);
	}));

	// Increase concurrency while jobs are queued; FIFO order must hold.
	limit.concurrency = 3;

	const idlePromise = limit.onIdle();
	await Promise.all([...promises, idlePromise]);

	t.deepEqual(order, [0, 1, 2, 3, 4, 5]);
	t.is(limit.activeCount, 0);
	t.is(limit.pendingCount, 0);
});

