	const limit = pLimit(1);
	const order = [];

	const outer = limit(async () => {
		await delay(20);
		order.push('outer');
		// Enqueue a new job before the outer job settles.
		limit(async () => {
			await delay(20);
			order.push('inner');
		});
	});

	let idle = false;
	const markIdle = async () => {
		await limit.onIdle();
		idle = true;
	};

